const numbers = [1, 2, 3, 4, 5];
const bigNumbers = numbers.filter(n => n > 3);
console.log(bigNumbers); // prints [4, 5]
// Only numbers greater than 3 made it through

// Written without arrow, to see it clearly:
const result = numbers.filter(function(n) {
  return n > 3;  // true = keep, false = skip
});
console.log(result); // [4, 5]

const users = [
  { name: 'Alice', active: true },
  { name: 'Bob', active: false },
  { name: 'Charlie', active: true }
];

const activeUsers = users.filter(user => user.active);
console.log(activeUsers);
// prints [{name: 'Alice', active: true}, {name: 'Charlie', active: true}]

const users = [
  { id: 1, name: 'Alice' },
  { id: 2, name: 'Bob' },
  { id: 3, name: 'Charlie' }
];

const user = users.find(u => u.id === 2);
console.log(user); // prints {id: 2, name: 'Bob'}

const nobody = users.find(u => u.id === 99);
console.log(nobody); // prints undefined

const items = [
  { color: 'red', size: 'M' },
  { color: 'blue', size: 'L' },
  { color: 'red', size: 'S' }
];

const allRed = items.filter(i => i.color === 'red');
// Returns [{color: 'red', size: 'M'}, {color: 'red', size: 'S'}]

const firstRed = items.find(i => i.color === 'red');
// Returns {color: 'red', size: 'M'} — only the FIRST one

