lesson.content:
const prices = [10, 20, 30];
const total = prices.reduce((sum, price) => sum + price, 0);
console.log(total); // prints 60

// prices = [10, 20, 30]
// .reduce((sum, price) => sum + price, 0)
//
// Step 1: sum = 0 (starting value), price = 10  → sum becomes 10
// Step 2: sum = 10,              price = 20  → sum becomes 30
// Step 3: sum = 30,              price = 30  → sum becomes 60
// Final result: 60

// Written without arrow function, to see it clearly:
const total = prices.reduce(function(sum, price) {
  return sum + price;
}, 0); // <-- starting value: 0

// sum starts at 0, then becomes 0 + 10 = 10, then 10 + 20 = 30, then 30 + 30 = 60

// WITHOUT starting value — see what happens with an empty array:
const empty = [];
// empty.reduce((sum, price) => sum + price);
// This throws an ERROR! Can't reduce an empty array without a starting value.

// WITH starting value:
empty.reduce((sum, price) => sum + price, 0);
// Returns 0 — no error, just the starting value.

// Manual loop version (long way):
let total = 0;
for (let i = 0; i < prices.length; i++) {
  total = total + prices[i];
}
console.log(total); // 60

// Reduce version (short way):
const total = prices.reduce((sum, price) => sum + price, 0);
console.log(total); // 60

// If input is [{price: 10}, {price: 20}, {price: 30}]
// Output should be 60
//
// Hint: items.reduce((total, item) => total + item.price, 0)
// Start at 0, add each item's price, return the final total

